//"'! SIMULATOR — Monte Carlo experiment separating thirder vs halfer betting.
//! Each awakening is an independent decision point; total payoff across
//! awakenings per trial determines which model'"'s betting strategy dominates.

use rand::prelude::*;

#[derive(Clone, Copy, Debug)]
enum CoinFlip { Heads, Tails }

/// Strategy type: given coin (unknown to agent), return bet direction.
type BetFn = fn(CoinFlip) -> bool;

fn simulate_one_trial(coin: CoinFlip, strategy: BetFn) -> f64 {
    let mut winnings = 0.0;
    match coin {
        CoinFlip::Heads => {
            let bet_on_heads = strategy(coin);
            if bet_on_heads { winnings += 1.0; } else { winnings -= 1.0; }
        }
        CoinFlip::Tails => {
            for _ in 0..2 {
                let bet_on_heads = strategy(coin);
                if bet_on_heads { winnings -= 1.0; } else { winnings += 1.0; }
            }
        }
    }
    winnings
}

#[derive(Debug, Default)]
struct Stats {
    total_winnings: f64,
    num_bets: u64,
    wins: u64,
    losses: u64,
    break_even: u64,
    profitable_trials: u64,
}

impl Stats {
    fn merge(&mut self, other: &Self) {
        self.total_winnings += other.total_winnings;
        self.num_bets += other.num_bets;
        self.wins += other.wins;
        self.losses += other.losses;
        self.break_even += other.break_even;
        self.profitable_trials += other.profitable_trials;
    }

    fn avg_per_bet(&self) -> f64 {
        if self.num_bets == 0 { return 0.0; }
        self.total_winnings / self.num_bets as f64
    }

    fn win_rate(&self) -> f64 {
        if self.num_bets == 0 { return 0.0; }
        (self.wins + self.break_even) as f64 / self.num_bets as f64
    }

    fn profit_pct(&self) -> f64 {
        let total = self.wins + self.losses + self.break_even;
        if total == 0 { return 0.0; }
        self.profitable_trials as f64 / total * 100.0
    }
}

fn run_single_thread(n_trials: usize, strategy: BetFn) -> Stats {
    let mut rng = thread_rng();
    let mut stats = Stats::default();

    for _ in 0..n_trials {
        let coin: CoinFlip = if rng.gen_bool(0.5) { CoinFlip::Heads } else { CoinFlip::Tails };
        let trial_result = simulate_one_trial(coin, strategy);

        let n_awake = if coin == CoinFlip::Heads { 1u64 } else { 2 };
        stats.num_bets += n_awake;
        if trial_result > 0.0 { stats.wins += 1; stats.profitable_trials += 1; }
        else if trial_result < 0.0 { stats.losses += 1; }
        else { stats.break_even += 1; }
        stats.total_winnings += trial_result;
    }
    stats
