//!
//! Core insight: the two camps make different PREDICTIONS about how people
//! will bet WHEN THE BET STRUCTURE IS KNOWN IN ADVANCE vs when decisions
//! are made at each awakening independently.

use std::collections::HashMap;

// ─── Protocol definitions ──────────────────────────────────────────────

#[derive(Debug)]
struct ProtocolSpec {
    id: &'"'static str,
    name: &'static str,
    n_subjects: usize,
    structure: ProtocolStructure,
    incentive: IncentiveScheme,
}

#[derive(Debug)]
enum ProtocolStructure {
    /// Standard SBP: subject sleeps, wakens 1 or 2 times, makes one bet each time.
    StandardSBP,
    /// Pre-commit variant: subject chooses a single strategy on Sunday before sleep.
    PreCommit,
    /// Separate-day variant: Monday and Tuesday bets are announced as separate independent games.
    DaySeparation,
    /// Lottery variant: subject picks which awakening(s) they want to win from.
    LotteryChoice,
}

#[derive(Debug)]
struct IncentiveScheme {
    bet_cost: f64,
    correct_payout: f64,
    wrong_loss: f64,
    participation_fee: f64,
    currency: &'static str,
}

