    println!("    Expected subject choice:  {}", pred.expected_preference);
    println!("    Discriminating power:     {}", pred.discriminating_power);
    println!();
}

fn format_confound(c: &Confound) {
    let sev_icon = match c.severity {
        "CRITICAL" => "████ CRITICAL",
        "HIGH"     => "███  HIGH",
        "MEDIUM"   => "██   MEDIUM",
        _          => "█    LOW",
    };
    println!("  [{}] {}", sev_icon, c.name);
    println!("    Problem: {}", c.description);
    println!("    Biases toward: {}", c.affects);
    println!("    Fix: {}", c.mitigation);
    println!();
}

