//"'! THESIS ENGINE -- Formal steelman of 1/3 (thirder) vs 1/2 (halfer),
//! identification of the precise ambiguity, and the decision-theoretic
//! payoff structure that makes each answer internally rational.
//!
//! The Sleeping Beauty problem (SBP):
//!   A coin is tossed Sunday night.
//!   - H -> Beauty wakes Mon only.
//!   - T -> Beauty wakes Mon AND Tue (memory-wiped between awakenings).
//!   Each awakening she learns "today is an awakening day" (no new info).
//!   P(R): "What is your credence that the coin landed Heads?"
//!
//! Two camps: HALFER P(H)=1/2     ,    THIRDER P(H)=1/3

// ─── Data types ────────────────────────────────────────────────────────

#[derive(Clone, Copy, Debug)]
enum CoinFlip {
    Heads,
    Tails,
}

#[derive(Clone, Copy, Debug, PartialEq)]
enum Day {
    Monday,
    Tuesday,
}

/// A single experimental trial: one coin flip x one run of the protocol.
#[derive(Debug)]
struct Trial {
    coin: CoinFlip,
    /// All awakenings produced this trial.
    awakenings: Vec<(Day, usize)>, // (day, awakening_index_within_day)
}

/// Bet offered at each awakening.
#[derive(Clone, Debug)]
struct Bet {
    payout_win: f64,         // net gain if correct
    payout_lose: f64,        // net loss if wrong (always negative)
}

// ─── Protocol generators ───────────────────────────────────────────────

fn generate_trial(coin: CoinFlip) -> Trial {
    let awakenings = match coin {
        CoinFlip::Heads => vec![(Day::Monday, 0)],
        CoinFlip::Tails => vec![
            (Day::Monday, 0),
            (Day::Tuesday, 0),
        ],
    };
    Trial { coin, awakenings }
}

fn generate_trials(n: usize) -> Vec<Trial> {
    let mut trials = Vec::with_capacity(n);
    let mut rng = rand::thread_rng();
    for _ in 0..n {
        let coin = if rng.gen_bool(0.5) { CoinFlip::Heads } else { CoinFlip::Tails };
        trials.push(generate_trial(coin));
    }
    trials
}

// ─── Credence models ───────────────────────────────────────────────────

/// Halfer model: P(H)=1/2. At each awakening, posterior = prior because
/// "I am being awakened" provides no new information.
struct Halfer;

impl Halfer {
    fn credence_heads(&self, _: Day) -> f64 { 0.5 }

    /// Optimal bet given credence c and bet parameters.
    fn optimal_bet(c: f64, bet: &Bet) -> bool {
        // Expected value of betting on heads:
        //   EV_H = c * payout_win + (1-c) * payout_lose
        // EV_T  = (1-c) * (-payout_win) + c * (-payout_lose)
        let ev_h = c * bet.payout_win + (1.0 - c) * bet.payout_lose;
        let ev_t = (1.0 - c) * (-bet.payout_win) + c * (-bet.payout_lose);
        ev_h >= ev_t
    }
}

/// Thirder model: P(H)=1/3. Among all possible awakenings, 1/3 are Heads.
/// Each awakening splits credence equally across reference-class members.
struct Thirder;

impl Thirder {
    fn credence_heads(&self, _: Day) -> f64 { 1.0 / 3.0 }

    fn optimal_bet(c: f64, bet: &Bet) -> bool {
        let ev_h = c * bet.payout_win + (1.0 - c) * bet.payout_lose;
        let ev_t = (1.0 - c) * (-bet.payout_win) + c * (-bet.payout_lose);
        ev_h >= ev_t
    }
}

// ─── Simulation engine ─────────────────────────────────────────────────

struct CumulativeEv {
    total_profit: f64,
    num_bets: u64,
    wins: u64,
}

impl CumulativeEv {
    fn avg_per_bet(&self) -> f64 { self.total_profit / self.num_bets as f64 }
    fn expected_value(&self) -> f64 { self.total_profit / self.num_bets as f64 }
    fn win_rate(&self) -> f64 { self.wins as f64 / self.num_bets as f64 }
}

fn evaluate_strategy_for_camp<F>(
    trials: &[Trial],
    bet: &Bet,
    cred_fn: F,
) -> CumulativeEv
where
    F: Fn(CoinFlip, Day) -> f64,
{
    let mut cum = CumulativeEv { total_profit: 0.0, num_bets: 0, wins: 0 };

    for trial in trials {
        for (_day, _idx) in &trial.awakenings {
            cum.num_bets += 1;
            let bet_on_heads = Halfer::optimal_bet(cred_fn(trial.coin, *_day), bet);

            let won = (bet_on_heads && trial.coin == CoinFlip::Heads)
                || (!bet_on_heads && trial.coin == CoinFlip::Tails);

            if won {
                cum.wins += 1;
                cum.total_profit += bet.payout_win;
            } else {
                cum.total_profit += bet.payout_lose;
            }
        }
    }
    cum
}

fn evaluate_always_tails(trials: &[Trial], bet: &Bet) -> CumulativeEv {
    let mut cum = CumulativeEv { total_profit: 0.0, num_bets: 0, wins: 0 };
    for trial in trials {
        for (_day, _idx) in &trial.awakenings {
            cum.num_bets += 1;
            // Always bet tails
            if trial.coin == CoinFlip::Tails {
                cum.wins += 1;
                cum.total_profit += bet.payout_win;
            } else {
                cum.total_profit += bet.payout_lose;
            }
        }
    }
    cum
}

fn evaluate_random_betting(trials: &[Trial], bet: &Bet) -> CumulativeEv {
    let mut cum = CumulativeEv { total_profit: 0.0, num_bets: 0, wins: 0 };
    let mut rng = rand::thread_rng();
    for trial in trials {
        for (_day, _idx) in &trial.awakenings {
            cum.num_bets += 1;
            let bet_on_heads = rng.gen_bool(0.5);
            let won = (bet_on_heads && trial.coin == CoinFlip::Heads)
                || (!bet_on_heads && trial.coin == CoinFlip::Tails);
            if won {
                cum.wins += 1;
                cum.total_profit += bet.payout_win;
            } else {
                cum.total_profit += bet.payout_lose;
            }
        }
    }
    cum
}

