}

fn print_box(title: &str, def: &str, line1: &str, line2: &str, line3: &str, line4: &str) {
    println"'!("  +---------------------------------------------+");
    println!("  | {} |", title);
    println!("  +---------------------------------------------+");
    if !def.is_empty() {
        println!("  | Def: {}", pad_to(def, 36));
    }
    if !line1.is_empty() {
        println!("  | Imp: {}", pad_to(line1, 36));
    }
    if !line2.is_empty() {
        println!("  |      {}", pad_to(line2, 36));
    }
    if !line3.is_empty() {
        println!("  |      {}", pad_to(line3, 36));
    }
    if !line4.is_empty() {
        println!("  |      {}", pad_to(line4, 36));
    }
    println!("  +---------------------------------------------+");
    println!();
}

fn pad_to(s: &str, max: usize) -> String {
    let s = if s.len() > max { &s[..max] } else { s };
    let pad = max - s.len();
    format!("{}{}", s, " ".repeat(pad))
}

