//"'! THESIS ENGINE -- Formal steelman of 1/3 (thirder) vs 1/2 (halfer),
//! identification of the precise ambiguity, and the decision-theoretic
//! payoff structure that makes each answer internally rational.

use rand::prelude::*;

#[derive(Clone, Copy, Debug, PartialEq)]
enum CoinFlip { Heads, Tails }

#[derive(Clone, Copy, Debug, PartialEq)]
enum Day { Monday, Tuesday }

struct Trial { coin: CoinFlip, awakenings: Vec<(Day, usize)> }

#[derive(Clone, Debug)]
struct Bet { payout_win: f64, payout_lose: f64 }

fn generate_trial(coin: CoinFlip) -> Trial {
    let awakenings = match coin {
        CoinFlip::Heads => vec![(Day::Monday, 0)],
        CoinFlip::Tails => vec![(Day::Monday, 0), (Day::Tuesday, 0)],
    };
    Trial { coin, awakenings }
}

fn generate_trials(n: usize) -> Vec<Trial> {
    let mut trials = Vec::with_capacity(n);
    let mut rng = rand::thread_rng();
    for _ in 0..n {
        let coin = if rng.gen_bool(0.5) { CoinFlip::Heads } else { CoinFlip::Tails };
        trials.push(generate_trial(coin));
    }
    trials
}

struct Halfer;
impl Halfer {
    fn credence(_day: Day) -> f64 { 0.5 }
    fn bet(c: f64, bet: &Bet) -> bool {
        let ev_h = c * bet.payout_win + (1.0 - c) * bet.payout_lose;
        let ev_t = (1.0 - c) * (-bet.payout_win) + c * (-bet.payout_lose);
        ev_h >= ev_t
    }
}

struct Thirder;
impl Thirder {
    fn credence(_day: Day) -> f64 { 1.0 / 3.0 }
    fn bet(c: f64, bet: &Bet) -> bool {
        let ev_h = c * bet.payout_win + (1.0 - c) * bet.payout_lose;
        let ev_t = (1.0 - c) * (-bet.payout_win) + c * (-bet.payout_lose);
        ev_h >= ev_t
    }
}

struct CumEv { total: f64, bets: u64, wins: u64 }
impl CumEv {
    fn per_bet(&self) -> f64 { self.total / self.bets as f64 }
    fn win_rate(&self) -> f64 { self.wins as f64 / self.bets as f64 }
}

fn eval<F>(trials: &[Trial], bet: &Bet, cred: F) -> CumEv
where F: Fn(CoinFlip, Day) -> f64,
{
    let mut c = CumEv { total: 0.0, bets: 0, wins: 0 };
    for t in trials {
        for (_d, _) in &t.awakenings {
            c.bets += 1;
            let h_b = Halfer::bet(cred(t.coin, *_d), bet);
            let won = (h_b && t.coin == CoinFlip::Heads)
                   || (!h_b && t.coin == CoinFlip::Tails);
            if won { c.wins += 1; c.total += bet.payout_win; }
            else { c.total += bet.payout_lose; }
        }
    }
    c
}

fn always_tails(trials: &[Trial], bet: &Bet) -> CumEv {
    let mut c = CumEv { total: 0.0, bets: 0, wins: 0 };
    for t in trials {
        for _ in &t.awakenings {
            c.bets += 1;
            if t.coin == CoinFlip::Tails { c.wins += 1; c.total += bet.payout_win; }
            else { c.total += bet.payout_lose; }
        }
    }
    c
}

fn random_bet(trials: &[Trial], bet: &Bet) -> CumEv {
    let mut c = CumEv { total: 0.0, bets: 0, wins: 0 };
    let mut rng = rand::thread_rng();
    for t in trials {
        for _ in &t.awakenings {
            c.bets += 1;
            let h_b = rng.gen_bool(0.5);
            let won = (h_b && t.coin == CoinFlip::Heads)
                   || (!h_b && t.coin == CoinFlip::Tails);
            if won { c.wins += 1; c.total += bet.payout_win; }
            else { c.total += bet.payout_lose; }
        }
    }
    c
}

fn show(label: &str, c: &CumEv) {
    println!("  [{}] Avg/bet: {:>+12.4}  Total: {:>+12.2}  Bets: {:>8.0}  Win%: {:>6.1}",
             label, c.per_bet(), c.total, c.bets as f64, c.win_rate() * 100.0);
}

