//"'! SIMULATOR -- Monte Carlo experiment separating thirder vs halfer betting.
//! Each awakening is an independent decision point.
//! Properly evaluates each camp'"'s distinct strategy under various stakes.

use rand::prelude::*;

#[derive(Clone, Copy, Debug, PartialEq)]
enum CoinFlip { Heads, Tails }

struct Stats {
    total_winnings: f64,
    num_bets: u64,
    wins: u64,
    profitable_trials: u64,
}

impl Stats {
    fn new() -> Self { Stats { total_winnings: 0.0, num_bets: 0, wins: 0, profitable_trials: 0 } }
    fn avg_per_bet(&self) -> f64 { self.total_winnings / self.num_bets as f64 }
    fn win_rate(&self) -> f64 { self.wins as f64 / self.num_bets as f64 }
    fn trial_profit_pct(&self) -> f64 { self.profitable_trials as f64 / self.num_bets as f64 * 100.0 }
}

/// Simulate trials with a custom credence per bet. Returns stats.
fn simulate_with_credence(n_trials: usize, credence_h: f64, payout_win: f64, payout_lose: f64) -> Stats {
    let mut rng = thread_rng();
    let mut s = Stats::new();

    for _ in 0..n_trials {
        let coin = if rng.gen_bool(0.5) { CoinFlip::Heads } else { CoinFlip::Tails };
        let n_awake = if coin == CoinFlip::Heads { 1u64 } else { 2 };

        // At each awakening, agent decides based on credence
        let ev_heads = credence_h * payout_win + (1.0 - credence_h) * payout_lose;
        let ev_tails = (1.0 - credence_h) * (-payout_win) + credence_h * (-payout_lose);
        let bet_heads = ev_heads >= ev_tails; // true = bet H, false = bet T

        // Accumulate result across awakenings
        let mut trial_result = 0.0;
        match coin {
            CoinFlip::Heads => {
                if bet_heads { trial_result += payout_win; }
                else { trial_result += payout_lose; }
            }
            CoinFlip::Tails => {
                if bet_heads { trial_result += 2.0 * payout_lose; } // wrong twice
                else { trial_result += 2.0 * payout_win; }         // right twice
            }
        }

        s.total_winnings += trial_result;
        s.num_bets += n_awake;
        if trial_result > 0.0 { s.profitable_trials += 1; }
        if (bet_heads && coin == CoinFlip::Heads) || ("'!bet_heads && coin == CoinFlip::Tails) {
            s.wins += n_awake;
        }
    }
    s
}

